    function mintConfirm(message) {
        if (activeConfirmation) return Promise.resolve(false);
        return new Promise(resolve=>{
            const overlay=targetDoc.createElement('div');overlay.id='mint-confirm';overlay.dataset.theme=isDayTime()?'day':'night';
            overlay.innerHTML=`<div class="mint-confirm-card" role="dialog" aria-modal="true" aria-labelledby="mint-confirm-title"><img src="${MINT_DAY_AVATAR}" alt="小序"><h3 id="mint-confirm-title">确认一下这件事</h3><p></p><div class="mint-row"><button data-answer="no">先等等</button><button data-answer="yes">确认</button></div></div>`;
            overlay.querySelector('p').textContent=message;
            const previous=targetDoc.activeElement;
            const finish=value=>{targetDoc.removeEventListener('keydown',keyboard,true);overlay.remove();activeConfirmation=null;previous?.focus?.();resolve(value);};
            const keyboard=e=>{
                if(e.key==='Escape'){e.preventDefault();finish(false);}
                else if(e.key==='Tab'){const buttons=[...overlay.querySelectorAll('button')];e.preventDefault();buttons[targetDoc.activeElement===buttons[0]?1:0].focus();}
            };
            activeConfirmation=()=>finish(false);targetDoc.body.appendChild(overlay);
            overlay.querySelector('[data-answer=no]').addEventListener('click',()=>finish(false),{once:true});
            overlay.querySelector('[data-answer=yes]').addEventListener('click',()=>finish(true),{once:true});
            overlay.addEventListener('click',e=>{if(e.target===overlay)finish(false);});
            targetDoc.addEventListener('keydown',keyboard,true);overlay.querySelector('[data-answer=no]').focus();
        });
    }
    async function copyMintMessage(text) {
        try { await targetWindow.navigator.clipboard.writeText(text); showCapsule('错误信息已复制'); }
        catch { const area=targetDoc.createElement('textarea');area.value=text;targetDoc.body.appendChild(area);area.select();const ok=targetDoc.execCommand?.('copy');area.remove();if(ok)showCapsule('错误信息已复制');else showCapsule('复制失败，请长按提示内容复制','warning'); }
    }

    const UI_PREFS_KEY='__mint_ui__';
    const DEFAULT_UI_PREFS={showPageNotices:false,showClickNotices:false,showDecorations:true};
    let uiPrefs={...DEFAULT_UI_PREFS};
    const MINT_DECORATIONS={gallery:'data:image/webp;base64,',history:'data:image/webp;base64,',settings:'data:image/webp;base64,'};
    function normalizeUiPrefs(value) {
        const result={...DEFAULT_UI_PREFS};
        for(const key of Object.keys(result))if(typeof value?.[key]==='boolean')result[key]=value[key];
        return result;
    }
    function placeFeedbackAboveTabs(viewHeight,navTop,gap=12) { return Math.max(18,Math.ceil(viewHeight-navTop+gap)); }
    function positionMintFeedback() {
        const box=targetDoc.getElementById('mint-feedback');if(!box)return;
        const panel=targetDoc.getElementById('aibar-panel');
        if(mountMintFeedback(box)){box.style.removeProperty('bottom');box.style.removeProperty('left');box.style.removeProperty('max-height');return;}
        const nav=panel?.querySelector('#mint-tabs');
        if(!nav||!nav.getClientRects().length){box.style.removeProperty('bottom');box.style.removeProperty('left');box.style.removeProperty('max-height');return;}
        const rect=nav.getBoundingClientRect();const viewHeight=targetWindow.innerHeight;
        box.style.bottom=placeFeedbackAboveTabs(viewHeight,rect.top)+'px';
        box.style.left=(rect.left+rect.width/2)+'px';
        const visualTop=targetWindow.visualViewport?.offsetTop||0;
        box.style.maxHeight=Math.max(60,rect.top-visualTop-24)+'px';
    }
    function syncUiPrefs(panel) {
        panel.dataset.decorations=uiPrefs.showDecorations?'on':'off';
        const fields={'mint-page-notices':'showPageNotices','mint-click-notices':'showClickNotices','mint-decoration-toggle':'showDecorations'};
        for(const [id,key]of Object.entries(fields)){const input=panel.querySelector('#'+id);if(input)input.checked=uiPrefs[key];}
    }
    function bindUiPrefs(panel) {
        syncUiPrefs(panel);
        const fields={'mint-page-notices':'showPageNotices','mint-click-notices':'showClickNotices','mint-decoration-toggle':'showDecorations'};
        for(const [id,key]of Object.entries(fields))on(panel.querySelector('#'+id),'change',async e=>{
            const next={...uiPrefs,[key]:e.target.checked};
            try{await saveConfig(UI_PREFS_KEY,next);uiPrefs=next;syncUiPrefs(panel);toast('界面偏好已保存','success');}
            catch(error){syncUiPrefs(panel);throw error;}
        });
        positionMintFeedback();
    }
    function mintEmptyState(kind,title,message) {
        return `<div class="mint-card mint-empty"><img class="mint-decoration mint-empty-mascot" src="${MINT_DECORATIONS[kind]||MINT_DAY_AVATAR}" alt=""><b>${esc(title)}</b><p class="mint-muted">${esc(message)}</p></div>`;
    }

    function generateUUID() {
        if (globalThis.crypto?.randomUUID) return crypto.randomUUID();
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
            const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
            return v.toString(16);
        });
    }

